//! Exact pinned admission retained through a private generation worker.
//! The owner context is not reconstructed from prompt/job fields. The
//! optional origin binds a job to the ZeroClaw `threetched.agent` schema.
use anyhow::{Context, Result};
use op_plugins::state_plugins::tched_router::generation::GenerationOwner;
use crate::method_contract_admission::AdmittedContract;
use std::{
    path::{Path, PathBuf},
    sync::Arc,
};

use crate::{
    interceptor::load_capability_grants,
    method_contract_admission,
    mutation_engine::MutationEngine,
    project_dispatch,
    sealed_schema_reader::{ManifestPinnedSchemaDocument, read_manifest_pinned_catalog},
};

pub(crate) const PLUGIN: &str = "tched_router";
const NATIVE_PLUGIN: &str = "threetched";
const NATIVE_AGENT_METHOD: &str = "agent";

#[derive(Clone)]
pub(crate) struct GenerationOrigin {
    pub(crate) schema_hash: String,
    pub(crate) schema_json: String,
    pub(crate) capability: String,
}
impl GenerationOrigin {
    pub(crate) fn admit(catalog: &Path, admitted: &AdmittedContract) -> Result<Self> {
        let catalog = read_manifest_pinned_catalog(catalog)?;
        let pinned = catalog
            .plugins
            .get(NATIVE_PLUGIN)
            .context("native threetched seal is absent")?;
        admitted.require_same(pinned)?;
        let declaration = pinned
            .schema
            .methods
            .get(NATIVE_AGENT_METHOD)
            .context("native threetched agent method is absent")?;
        let capability = declaration
            .required_capability
            .as_deref()
            .context("native threetched agent capability is absent")?;
        method_contract_admission::admit_pinned_compiled_method(
            pinned,
            NATIVE_PLUGIN,
            NATIVE_AGENT_METHOD,
            Some(capability),
        )?;
        anyhow::ensure!(
            serde_json::to_value(admitted)? == serde_json::to_value(&pinned.schema)?,
            "native threetched seal changed after admission"
        );
        Ok(Self {
            schema_hash: pinned.schema_hash.clone(),
            schema_json: pinned.blob.schema_json.clone(),
            capability: capability.to_owned(),
        })
    }
}

