fn parse_unix_to_tcp(raw: &str) -> Result<Spec, String> {
    let (sock, target) = raw
        .split_once('=')
        .ok_or_else(|| format!("--unix-to-tcp expects <sock>=<host>:<port>, got {raw:?}"))?;
    let (host, port) = target
        .rsplit_once(':')
        .ok_or_else(|| format!("--unix-to-tcp target expects <host>:<port>, got {target:?}"))?;
