fn parse_args(args: &[String]) -> Result<Vec<Spec>, String> {
    let mut specs = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let flag = args[i].as_str();
        let value = args
            .get(i + 1)
            .ok_or_else(|| format!("{flag} requires a value"))?;
        match flag {

