/// Parses a tool-use ack publish payload. The payload is the serialized
/// `ResponseCommittedSignal` receipt fields only; anything else is refused.
pub(crate) fn parse_tool_use_ack(payload: &[u8]) -> Result<ToolUseAck, String> {
    #[derive(serde::Deserialize)]
    struct Wire {
        owner_key: String,
        turn_id: String,
        turn_hash: String,
    }
    let wire: Wire = serde_json::from_slice(payload)
        .map_err(|error| format!("tool-use ack payload does not match its receipt shape: {error}"))?;
    if !op_plugins::state_plugins::emqx::valid_owner_key(&wire.owner_key) {
        return Err("tool-use ack owner key is not 64 hex characters".into());
    }
    Ok(ToolUseAck {
        owner_key: wire.owner_key,
        turn_id: wire.turn_id,
        turn_hash: wire.turn_hash,
    })
}

