//! op-plugins: Plugin system with state management and snowball footprints
//!
//! Features:
//! - Plugin trait with desired state management
//! - State plugins for network, LXC, systemd, OpenFlow, etc.
//! - BTRFS subvolume storage per plugin
//! - Automatic hash footprints for snowball audit trail
//! - Auto-creation of missing plugins
//! - Lifecycle hooks
//! - Canonical plugin-document persistence into the schema catalog

pub mod auto_create;
pub mod builtin;
pub mod canonical;
pub mod chat;
pub mod dynamic_loading;
pub mod plugin;
pub mod registry;
pub mod service_def;
pub mod threetched_runtime_types;
pub mod state;

// State plugins - each manages a specific domain
pub mod default_registry;
pub mod state_plugins;

pub use auto_create::AutoPlugin;
…
pub use state::{ChangeOperation, DesiredState, StateChange, ValidationResult};

// ── Canonical PluginSchema authority surface ───────────────────────────────
// "The plugin is the schema." The schema *type* physically lives in the lowest
// crate (op-state-store, zero workspace deps) to avoid dependency cycles, but
// op-plugins is the single authoritative *import surface*: every consumer
// (cognitive, projection, web, gRPC) imports schema types from `op_plugins`.
// op-state-store is retired as a public schema surface — code that still (or
// mistakenly) reaches for the old path can resolve through this alias instead.
pub use op_state_store::plugin_schema::{
    PluginSchemaBuilder, ValidationResult as SchemaValidationResult,
};
pub use op_state_store::{Constraint, FieldSchema, FieldType, PluginSchema, ReadOnlyCondition};

/// Canonical input/contract schema for the cognitive gateway, including the
/// `code_search` / `code_context` / `code_index` tool inputs (each carrying its
/// OSCAL subid). This is the authoritative accessor; tools derive their
/// `input_schema()` from this via `PluginSchema::field_input_schema(...)`.
pub fn cognitive_plugin_schema() -> PluginSchema {
    state_plugins::cognitive::cognitive_schema()
}

/// Deterministically materialize the initial D-Bus projection state from a
/// plugin schema. This is the bootstrap counterpart to the MutationEngine's
/// normal projection writes: it is used only when no live projection exists.
pub fn projection_seed_state_from_schema(schema: &PluginSchema) -> simd_json::OwnedValue {
    state_plugins::plugin_scaffold_helpers::materialize_state_from_schema(schema)
}

// Re-export chat types
pub use chat::{
    ChatMessage, ChatRequest, ChatResponse, ChatRole, ExecutionStatus, TokenUsage, ToolCall,
};

/// Prelude for convenient imports
pub mod prelude { … }
pub mod state_publisher;

//! Wire DTOs and size bounds shared by the threetched runtime chat clients.
//!
//! This module owns no PluginSchema, method declarations, capabilities, or
//! dispatch. Native method authority remains with the captured threetched
//! contract; callers retain their own admission and identity checks.

use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;

/// Maximum serialized request bytes accepted by native runtime chat callers.
pub const MAX_CHAT_REQUEST_BYTES: usize = 1024 * 1024;
/// Maximum response bytes accepted from native runtime chat callers.
pub const MAX_CHAT_RESPONSE_BYTES: usize = 8 * 1024 * 1024;

/// One chat turn carried between authenticated bridge flows and the runtime.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
pub struct RuntimeChatMessage {
    /// OpenAI-compatible message role such as `system`, `user`, or `assistant`.
    pub role: String,
    /// Text content carried by this conversation turn.
    pub content: String,
}

/// Chat request shared by EMQX agent execution and cognitive runtime callers.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ChatInput {
    /// Compatibility form for callers sending a single user turn.
    #[serde(default)]
    pub message: String,
    /// Full ordered conversation. When non-empty this takes precedence over `message`.
    #[serde(default)]
    pub messages: Vec<RuntimeChatMessage>,
    /// Provider id, route, or alias. Empty uses the caller's selected provider.
    #[serde(default)]
    pub provider: String,
    /// Model id or route hint. Empty uses the caller's selected model.
    #[serde(default)]
    pub model: String,
    /// Optional correlation label scoped by the verified principal/session; never identity.
    #[serde(default)]
    pub conversation_id: Option<String>,
}

/// Chat result shared by EMQX agent execution and cognitive runtime callers.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ChatOutput {
    /// Assistant response text.
    pub content: String,
    /// Upstream provider selected when the A2A request was submitted.
    /// A2A does not report attribution for an upstream fallback.
    pub provider: String,
    /// Upstream model selected when the A2A request was submitted.
    pub model: String,
    /// Provider finish reason, or an empty string when none was supplied.
    pub finish_reason: String,
    /// Provider-specific token usage object.
    pub usage: JsonValue,
}

