1://! Capture-backed accessors for the native threetched configuration contract.
2://! The schema is captured from the verified threetched binary at every seal
3://! through the threetched plugin's pinned capture; nothing is imported or
4://! stored here. All section/method schemas derive from that one capture.
5:use serde_json::{Map, Value};
6:use std::collections::BTreeSet;
7:
8:pub fn document() -> &'static Value {
9:    super::threetched::config_schema()
10:        .expect("threetched config schema must be captured from the binary at seal")
11:}
12:
13:fn references(node: &Value, out: &mut BTreeSet<String>) {
14:    match node {
15:        Value::Object(map) => {
16:            if let Some(name) = map
17:                .get("$ref")
18:                .and_then(Value::as_str)
19:                .and_then(|r| r.strip_prefix("#/$defs/"))
20:            {
21:                out.insert(name.to_string());
22:            }
23:            for child in map.values() {
24:                references(child, out);
25:            }
26:        }
27:        Value::Array(items) => {
28:            for child in items {
29:                references(child, out);
30:            }
31:        }
32:        _ => {}
33:    }
34:}
35:
36:/// Derive a self-contained section from the plugin contract, retaining transitive definitions.
37:pub fn section_from(document: &Value, key: &str) -> Value {
38:    let property = &document["properties"][key];
39:    let mut section = property
40:        .as_object()
41:        .expect("config property is an object")
42:        .clone();
43:    let definitions = document["$defs"]
44:        .as_object()
45:        .expect("config contract has definitions");
46:    let mut pending = BTreeSet::new();
47:    let mut included = Map::new();
48:    references(property, &mut pending);
49:    while let Some(name) = pending.pop_first() {
50:        if included.contains_key(&name) {
51:            continue;
52:        }
53:        let definition = definitions.get(&name).expect("config reference resolves");
54:        references(definition, &mut pending);
55:        included.insert(name, definition.clone());
56:    }
57:    if !included.is_empty() {
58:        section.insert("$defs".into(), Value::Object(included));
59:    }
60:    Value::Object(section)
61:}
62:
63:pub fn section(key: &str) -> Value {
64:    section_from(document(), key)
65:}
