237:    test_db.insert("key", "value");
238:    assert_eq!(test_db.get("key"), Some("value".into()));
239:}
240:```
241:
242:### Test Helpers
243:
244:```rust
245:#[cfg(test)]
246:mod tests {
247:    use super::*;
248:
